using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Caching.Memory; using Microsoft.Extensions.DependencyInjection; using MyFundex.BuildingBlocks.Abstractions; using MyFundex.BuildingBlocks.Domain; using MyFundex.BuildingBlocks.Persistence;using MyFundex.Contracts;
namespace MyFundex.Configuration;
public sealed class SystemSetting:EntityBase{public Guid SettingId{get;set;} public string SettingKey{get;set;}=""; public string SettingValue{get;set;}=""; public string ValueType{get;set;}="String"; public string Category{get;set;}="General"; public string Environment{get;set;}="UAT"; public bool IsSensitive{get;set;} public string? Description{get;set;}}
public sealed class ConfigurationDbContext(DbContextOptions<ConfigurationDbContext> o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<SystemSetting>Settings=>Set<SystemSetting>();protected override void OnModelCreating(ModelBuilder m) => ConfigureModel(m); public static void ConfigureModel(ModelBuilder m) {m.HasDefaultSchema("configuration");ConfigureEntity(m.Entity<SystemSetting>());m.Entity<SystemSetting>().HasIndex(x=>new{x.SettingKey,x.Environment}).IsUnique().HasFilter("\"IsDeleted\" = false");}}
public static class ConfigurationModule{public static IServiceCollection AddConfigurationModule(this IServiceCollection s,string cs){s.AddMemoryCache();s.AddDbContext<ConfigurationDbContext>(o=>o.UseNpgsql(cs));s.AddScoped<IRuntimeSettings,RuntimeSettings>();return s;}}
